const tz = 'Europe/Paris';
const now = DateTime.now().setZone(tz);
const today = now.toISODate();
const tomorrow = now.plus({ days: 1 }).toISODate();

function rows(name) {
  try {
    return $(name).all().map(function (i) { return i.json; }).filter(function (j) { return j && Object.keys(j).length > 0; });
  } catch (e) {
    return [];
  }
}

const comptes = [
  { compte: 'perso', cal: 'Google Agenda - Lire RDV perso', inbox: 'Gmail - Lire reçus perso', sent: 'Gmail - Lire envoyés perso' },
  { compte: 'ecole', cal: 'Google Agenda - Lire RDV ecole', inbox: 'Gmail - Lire reçus ecole', sent: 'Gmail - Lire envoyés ecole' },
  { compte: 'pro', cal: 'Google Agenda - Lire RDV pro', inbox: 'Gmail - Lire reçus pro', sent: 'Gmail - Lire envoyés pro' }
];

const runs = rows('Data Table - Lire dernier passage').filter(function (r) { return r.lance_le; });
const lastTs = runs.length ? new Date(runs[0].lance_le).getTime() : now.minus({ days: 1 }).toMillis();

const seen = {};
const rdvJour = [];
const rdvDemain = [];
comptes.forEach(function (c) {
  rows(c.cal).forEach(function (ev) {
    if (!ev.id || ev.status === 'cancelled' || !ev.start) return;
    const key = ev.iCalUID || ev.id;
    if (seen[key]) return;
    seen[key] = true;
    const attendees = ev.attendees || [];
    const me = attendees.find(function (a) { return a.self; });
    if (me && me.responseStatus === 'declined') return;
    const allDay = !ev.start.dateTime;
    const start = allDay ? DateTime.fromISO(ev.start.date, { zone: tz }) : DateTime.fromISO(ev.start.dateTime).setZone(tz);
    const end = allDay ? DateTime.fromISO(ev.end.date, { zone: tz }) : DateTime.fromISO(ev.end.dateTime).setZone(tz);
    const organisateurMoi = !!(ev.organizer && ev.organizer.self);
    const autres = attendees.filter(function (a) { return !a.self && !a.resource; }).map(function (a) { return a.displayName || a.email; });
    const lieu = ev.location ? ev.location : (ev.hangoutLink ? 'Google Meet' : '');
    const rdv = {
      event_id: ev.id,
      compte: c.compte,
      titre: ev.summary || '(sans titre)',
      journee: allDay,
      debut: allDay ? '' : start.toFormat('HH:mm'),
      fin: allDay ? '' : end.toFormat('HH:mm'),
      debut_iso: start.toISO(),
      fin_iso: end.toISO(),
      lieu: lieu,
      avec: autres.slice(0, 3).join(', '),
      organisateur_moi: organisateurMoi,
      mon_statut: me ? me.responseStatus : 'accepted',
      declinable: !!me && !organisateurMoi
    };
    const sd = start.toISODate();
    const ed = end.toISODate();
    const coversToday = allDay ? (sd <= today && ed > today) : sd === today;
    const coversTomorrow = allDay ? (sd <= tomorrow && ed > tomorrow) : sd === tomorrow;
    if (coversToday) rdvJour.push(rdv);
    else if (coversTomorrow) rdvDemain.push(rdv);
  });
});

rdvJour.sort(function (a, b) {
  if (a.journee !== b.journee) return a.journee ? -1 : 1;
  return a.debut_iso < b.debut_iso ? -1 : (a.debut_iso > b.debut_iso ? 1 : 0);
});

const conflits = [];
const timed = rdvJour.filter(function (r) { return !r.journee; });
for (let i = 0; i < timed.length; i++) {
  for (let j = i + 1; j < timed.length; j++) {
    const a = timed[i];
    const b = timed[j];
    if (a.debut_iso < b.fin_iso && b.debut_iso < a.fin_iso) conflits.push({ a: a, b: b });
  }
}

const demainTimed = rdvDemain.filter(function (r) { return !r.journee; }).sort(function (a, b) { return a.debut_iso < b.debut_iso ? -1 : 1; });
const demain = { nb: rdvDemain.length, premier: demainTimed.length ? demainTimed[0].debut : '' };

function senderEmail(from) {
  const s = String(from || '');
  const m = s.match(/<([^>]+)>/);
  return (m ? m[1] : s).trim().toLowerCase();
}
function senderName(from) {
  const s = String(from || '');
  const i = s.indexOf('<');
  const n = (i > 0 ? s.slice(0, i) : s).replace(/"/g, '').trim();
  return n || senderEmail(s);
}

const pendingByThread = {};
rows('Data Table - Lire mails en attente').forEach(function (p) { if (p.thread_id) pendingByThread[p.thread_id] = p; });

const nouveaux = [];
const gardes = [];
comptes.forEach(function (c) {
  const received = {};
  const sentMax = {};
  rows(c.sent).forEach(function (m) {
    if (!m.threadId) return;
    const t = Number(m.internalDate || 0);
    if (!sentMax[m.threadId] || t > sentMax[m.threadId]) sentMax[m.threadId] = t;
  });
  rows(c.inbox).forEach(function (m) {
    if (!m.threadId) return;
    const t = Number(m.internalDate || 0);
    if (!received[m.threadId] || t > received[m.threadId].t) received[m.threadId] = { t: t, m: m };
  });
  Object.keys(received).forEach(function (tid) {
    const r = received[tid];
    if ((sentMax[tid] || 0) > r.t) return;
    const p = pendingByThread[tid];
    if (p) {
      const recu = DateTime.fromJSDate(new Date(p.recu_le)).setZone(tz);
      gardes.push(Object.assign({}, p, { attente_jours: Math.max(0, Math.floor(now.startOf('day').diff(recu.startOf('day'), 'days').days)) }));
      return;
    }
    if (r.t > lastTs) {
      nouveaux.push({
        id: tid,
        compte: c.compte,
        de: senderName(r.m.From),
        email: senderEmail(r.m.From),
        objet: r.m.Subject || '(sans objet)',
        extrait: String(r.m.snippet || '').slice(0, 500),
        recu_le: new Date(r.t).toISOString()
      });
    }
  });
});

const feedback = rows('Data Table - Lire exemples pas importants').slice(0, 20).map(function (f) { return '- ' + f.expediteur + ' | ' + f.objet + ' | ' + f.compte; }).join('\n');
const payload = { mails: nouveaux.map(function (m) { return { id: m.id, compte: m.compte, de: m.de + ' <' + m.email + '>', objet: m.objet, extrait: m.extrait }; }) };

return [{ json: { today: today, rdvJour: rdvJour, conflits: conflits, demain: demain, nouveaux: nouveaux, gardes: gardes, feedback: feedback || '(aucun)', payload: JSON.stringify(payload) } }];

const tz = 'Europe/Paris';
const now = DateTime.now().setZone(tz);
const prep = $('Code - Préparer RDV, conflits et mails').first().json;
const raw = $input.first().json || {};

let txt = '';
if (typeof raw.merged_response === 'string') txt = raw.merged_response;
else if (Array.isArray(raw.content)) txt = raw.content.filter(function (c) { return c.type === 'text'; }).map(function (c) { return c.text; }).join('\n');
else if (typeof raw.text === 'string') txt = raw.text;
else if (Array.isArray(raw.output)) txt = raw.output.filter(function (o) { return o && o.type === 'message'; }).map(function (o) { return (o.content || []).filter(function (c) { return c.type === 'output_text'; }).map(function (c) { return c.text; }).join('\n'); }).join('\n');
else if (typeof raw.output === 'string') txt = raw.output;

let tri = null;
try {
  const s = txt.indexOf('{');
  const e = txt.lastIndexOf('}');
  const parsed = JSON.parse(txt.slice(s, e + 1));
  tri = Array.isArray(parsed.mails) ? parsed.mails : null;
} catch (err) {
  tri = null;
}

const byId = {};
prep.nouveaux.forEach(function (m) { byId[m.id] = m; });

let nouveauxGardes;
if (tri === null) {
  nouveauxGardes = prep.nouveaux.map(function (m) { return Object.assign({}, m, { attendu: '', priorite: 'normale', nouveau: true, attente_jours: 0 }); });
} else {
  nouveauxGardes = tri.filter(function (t) { return t && byId[t.id]; }).map(function (t) {
    return Object.assign({}, byId[t.id], { attendu: t.attendu || '', priorite: t.priorite === 'haute' ? 'haute' : 'normale', nouveau: true, attente_jours: 0 });
  });
}
const anciens = prep.gardes.map(function (p) {
  return { id: p.thread_id, compte: p.compte, de: p.de, email: p.email || '', objet: p.objet, attendu: p.attendu || '', priorite: p.priorite || 'normale', recu_le: p.recu_le, attente_jours: p.attente_jours, nouveau: false };
});
const mails = nouveauxGardes.concat(anciens).sort(function (a, b) {
  if (a.priorite !== b.priorite) return a.priorite === 'haute' ? -1 : 1;
  return b.attente_jours - a.attente_jours;
});

function esc(s) { return String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); }
function ligneRdv(r) {
  const h = r.journee ? 'Journée' : (r.debut + '–' + r.fin);
  let s = h + ' ' + esc(r.titre);
  if (r.avec) s += ' avec ' + esc(r.avec);
  if (r.lieu) s += ', ' + esc(r.lieu);
  s += ' (' + r.compte + (r.organisateur_moi ? ', tu organises' : '') + ')';
  return s;
}

const L = [];
L.push('<b>Récap du ' + now.setLocale('fr').toFormat('cccc d LLLL') + '</b>');
if (prep.conflits.length) {
  L.push('');
  L.push('<b>Conflit</b>');
  prep.conflits.forEach(function (k) {
    L.push('· ' + k.a.debut + ' ' + esc(k.a.titre) + ' (' + k.a.compte + ') chevauche ' + k.b.debut + ' ' + esc(k.b.titre) + ' (' + k.b.compte + ')');
  });
}
L.push('');
L.push('<b>Rendez-vous</b>');
if (!prep.rdvJour.length) L.push('· Rien de prévu');
prep.rdvJour.forEach(function (r) { L.push('· ' + ligneRdv(r)); });
L.push('');
L.push('<b>Mails en attente</b>');
if (!mails.length) L.push('· Aucun mail en attente');
mails.forEach(function (m) {
  const tags = [];
  if (m.priorite === 'haute') tags.push('[haute]');
  tags.push(m.nouveau ? '[nouveau]' : '[' + m.attente_jours + ' j]');
  L.push('· ' + tags.join(' ') + ' ' + esc(m.de) + ' (' + m.compte + ') — ' + esc(m.objet) + (m.attendu ? ' : ' + esc(m.attendu) : ''));
});
L.push('');
L.push(prep.demain.nb ? 'Demain : ' + prep.demain.nb + ' RDV' + (prep.demain.premier ? ', premier à ' + prep.demain.premier : '') : 'Demain : rien de prévu');
if (tri === null && prep.nouveaux.length) {
  L.push('');
  L.push('<i>Tri indisponible ce matin : nouveaux mails listés sans résumé.</i>');
}
let texte = L.join('\n');
if (texte.length > 4000) texte = texte.slice(0, 3990) + '\n…';

const runId = now.toFormat('yyyyLLdd');
const nowIso = now.toISO();
const finJour = now.endOf('day').toISO();
const boutons = [];
let n = 0;
prep.rdvJour.filter(function (r) { return r.declinable && !r.journee && r.debut_iso > nowIso; }).forEach(function (r) {
  n = n + 1;
  const id = runId + '-R' + n;
  const libelle = r.debut + ' ' + r.titre + ' (' + r.compte + ')';
  boutons.push({
    bouton_id: id, run_id: runId, action: 'decliner', compte: r.compte, calendar_id: 'primary', event_id: r.event_id, thread_id: '',
    debut_rdv: r.debut_iso, libelle: libelle, statut_avant: r.mon_statut, statut: 'en_attente', expediteur: '', objet: '',
    texte_message: 'RDV · ' + esc(libelle), bouton_texte: 'Décliner', callback: id + '|D'
  });
});
mails.forEach(function (m) {
  n = n + 1;
  const id = runId + '-M' + n;
  const libelle = m.de + ' — ' + m.objet + ' (' + m.compte + ')';
  boutons.push({
    bouton_id: id, run_id: runId, action: 'pas_important', compte: m.compte, calendar_id: '', event_id: '', thread_id: m.id,
    debut_rdv: finJour, libelle: libelle, statut_avant: '', statut: 'en_attente', expediteur: m.email || m.de, objet: m.objet,
    texte_message: 'Mail · ' + esc(libelle), bouton_texte: 'Pas important', callback: id + '|I'
  });
});

const attente = mails.map(function (m) {
  return { thread_id: m.id, compte: m.compte, de: m.de, email: m.email || '', objet: m.objet, attendu: m.attendu, priorite: m.priorite, recu_le: m.recu_le };
});

return [{ json: {
  texte: texte,
  boutons: boutons,
  attente: attente,
  run: { run_id: runId, lance_le: nowIso, nb_rdv: prep.rdvJour.length, nb_mails: mails.length, elements: JSON.stringify({ rdv: prep.rdvJour, mails: mails, conflits: prep.conflits, demain: prep.demain }), statut: 'ok' }
} }];

